SELECT DISTINCT ?researcher WHERE {
  ?researcher <https://spinach.local/leads> ?project ; <https://spinach.local/worksAt> ?institution .
  ?institution <https://spinach.local/locatedIn> ?city .
  ?city <https://spinach.local/country> <https://spinach.local/country1> .
  ?project <https://spinach.local/topic> <https://spinach.local/topic3> .
  FILTER NOT EXISTS {
    ?researcher <https://spinach.local/authored> ?paper .
    ?paper <https://spinach.local/status> <https://spinach.local/retracted> .
  }
}

SELECT DISTINCT ?researcher ?project WHERE {
  ?researcher <https://spinach.local/worksAt> ?institution .
  ?institution <https://spinach.local/locatedIn> ?city .
  ?city <https://spinach.local/country> <https://spinach.local/country1> .
  ?researcher <https://spinach.local/leads> ?project .
  ?project <https://spinach.local/topic> <https://spinach.local/topic3> .
  FILTER NOT EXISTS {
    ?paper <https://spinach.local/authored> ?researcher .
    ?paper <https://spinach.local/status> <https://spinach.local/retracted> .
  }
} ORDER BY ?researcher ?project
